                    uHead) !== 'failure';
        }
        machineUnparkVf = greenRollupVf || headMovedCleanVf;
        machineUnparkWhyVf = greenRollupVf
            ? 'the current head checks are GREEN'
            : 'the head moved past the park carrying no red verdict of its own';
    }
