        var sm = makeSmAgent(Object.assign(vfConfig('a', 'b'), {
            github: {
                items: [vfItem(202, { labels: ['validation_failed'], headSha: 'aa11bb22cc' })],
                prStatus: { checkConclusion: 'none' }
            },
