            }
            if (m && opts.committers && opts.committers[m[1]] !== undefined) {
                return '"' + opts.committers[m[1]] + '"';
            }
            return '';
        };
    }
    function vfDispatched(cmdList) {
        return cmdList.some(function (c) { return c.command.indexOf('gh workflow run') === 0; });
    }
